from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
from scipy.linalg import solve  # noqa: E402
from scipy.spatial.distance import cdist  # noqa: E402


NODE_COUNTS = [50, 100, 500, 1000, 2000]
EPSILONS = [0.75, 1.5, 3.0]
EVAL_SIZE = 500
SEED = 4
NUGGET = 1e-10
DOMAIN_LOW = -1.0
DOMAIN_HIGH = 1.0


def target_field(x: np.ndarray) -> np.ndarray:
    x0 = x[:, 0]
    x1 = x[:, 1]
    return (
        np.sin(2.0 * np.pi * x0) * np.cos(3.0 * np.pi * x1)
        + 0.2 * np.exp(-5.0 * ((x0 - 0.25) ** 2 + (x1 + 0.10) ** 2))
    )


def c4_matern_kernel(
    x: np.ndarray, y: np.ndarray, epsilon: float
) -> np.ndarray:
    r = cdist(x, y)
    z = epsilon * r
    return np.exp(-z) * (3.0 + 3.0 * z + z**2)


def relative_l2(reference: np.ndarray, approx: np.ndarray) -> float:
    return float(
        np.linalg.norm(reference - approx) / np.linalg.norm(reference)
    )


def distinct_uniform_points(
    rng: np.random.Generator,
    n: int,
    low: float,
    high: float,
    dim: int = 2,
) -> np.ndarray:
    points: list[tuple[float, ...]] = []
    seen: set[tuple[float, ...]] = set()
    while len(points) < n:
        batch = rng.uniform(low, high, size=(max(32, n - len(points)), dim))
        for row in batch:
            key = tuple(float(v) for v in row)
            if key not in seen:
                seen.add(key)
                points.append(key)
                if len(points) == n:
                    break
    return np.asarray(points, dtype=float)


@dataclass
class GlobalScalarInterpolant:
    epsilon: float
    nugget: float = NUGGET
    x_train: np.ndarray | None = None
    weights: np.ndarray | None = None

    def fit(
        self, x_train: np.ndarray, y_train: np.ndarray
    ) -> "GlobalScalarInterpolant":
        self.x_train = np.asarray(x_train, dtype=float)
        y_train = np.asarray(y_train, dtype=float)
        k = c4_matern_kernel(self.x_train, self.x_train, self.epsilon)
        k = k + self.nugget * np.eye(k.shape[0])
        self.weights = solve(k, y_train, assume_a="pos")
        return self

    def predict(self, x_eval: np.ndarray) -> np.ndarray:
        if self.x_train is None or self.weights is None:
            raise RuntimeError("Call fit before predict.")
        k_eval = c4_matern_kernel(
            np.asarray(x_eval, dtype=float), self.x_train, self.epsilon
        )
        return k_eval @ self.weights


def sample_points(rng: np.random.Generator, n: int) -> np.ndarray:
    return distinct_uniform_points(rng, n, DOMAIN_LOW, DOMAIN_HIGH)


def output_dir() -> Path:
    path = Path(os.environ.get("RAGSYSTEM_OUTPUT_DIR", ".")).resolve()
    path.mkdir(parents=True, exist_ok=True)
    return path


def main() -> None:
    rng = np.random.default_rng(SEED)

    outdir = output_dir()
    x_eval = sample_points(rng, EVAL_SIZE)
    y_true = target_field(x_eval)

    errors = np.zeros((len(NODE_COUNTS), len(EPSILONS)))
    representative = None

    for i, n in enumerate(NODE_COUNTS):
        x_train = sample_points(rng, n)
        y_train = target_field(x_train)
        for j, epsilon in enumerate(EPSILONS):
            model = GlobalScalarInterpolant(epsilon=epsilon).fit(
                x_train, y_train
            )
            y_pred = model.predict(x_eval)
            err = relative_l2(y_true, y_pred)
            errors[i, j] = err
            print(
                f"N={n:4d}, epsilon={epsilon:5.2f}, relL2={err:.3e}"
            )
            if representative is None or (
                n == NODE_COUNTS[-1] and epsilon == EPSILONS[1]
            ):
                representative = (x_train, x_eval, y_pred, epsilon, n)

    error_path = outdir / "easy_scalar_c4_matern_errors.txt"
    with error_path.open("w", encoding="utf-8") as fh:
        fh.write("# generator=scientific_driver_v1\n")
        fh.write("# domain=[-1,1]x[-1,1]\n")
        fh.write("# sampling=uniform_random\n")
        fh.write(f"# rng_seed={SEED}\n")
        fh.write(f"# evaluation_nodes={EVAL_SIZE}\n")
        fh.write("# columns: N epsilon rel_l2\n")
        for i, n in enumerate(NODE_COUNTS):
            for j, epsilon in enumerate(EPSILONS):
                fh.write(
                    f"{n} {epsilon:.8f} {errors[i, j]:.16e}\n"
                )

    fig, ax = plt.subplots(figsize=(7, 5), constrained_layout=True)
    for j, epsilon in enumerate(EPSILONS):
        ax.loglog(
            NODE_COUNTS,
            errors[:, j],
            "-o",
            linewidth=1.8,
            label=fr"$\epsilon={epsilon}$",
        )
    ax.set_xlabel("Number of interpolation nodes")
    ax.set_ylabel("Relative $L^2$ error")
    ax.set_title("Scalar C4 Matern interpolation ablation")
    ax.grid(True, which="both", alpha=0.25)
    ax.legend()
    fig.savefig(outdir / "easy_scalar_c4_matern_ablation.png", dpi=160)
    plt.close(fig)

    if representative is not None:
        _, x_rep, y_rep, epsilon_rep, n_rep = representative
        point_error = np.abs(y_true - y_rep)
        fig2, axes = plt.subplots(
            1, 3, figsize=(13, 4), constrained_layout=True
        )
        sc0 = axes[0].scatter(
            x_rep[:, 0], x_rep[:, 1], c=y_true, s=6, cmap="viridis"
        )
        axes[0].set_title("True field")
        fig2.colorbar(sc0, ax=axes[0])
        sc1 = axes[1].scatter(
            x_rep[:, 0], x_rep[:, 1], c=y_rep, s=6, cmap="viridis"
        )
        axes[1].set_title(
            f"Predicted field\nN={n_rep}, epsilon={epsilon_rep}"
        )
        fig2.colorbar(sc1, ax=axes[1])
        sc2 = axes[2].scatter(
            x_rep[:, 0], x_rep[:, 1], c=point_error, s=6, cmap="magma"
        )
        axes[2].set_title("Pointwise absolute error")
        fig2.colorbar(sc2, ax=axes[2])
        for ax in axes:
            ax.set_xlabel("x")
            ax.set_ylabel("y")
            ax.set_aspect("equal")
        fig2.savefig(
            outdir / "easy_scalar_c4_matern_fields.png", dpi=160
        )
        plt.close(fig2)


if __name__ == "__main__":
    main()
